const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcanoPoint = ee.Geometry.Point([-19.62, 63.63]);

  // Define regions: north and south of volcano (50km radius each)
  const northRegion = ee.Geometry.Point([-19.62, 64.13]).buffer(50000); // ~50km north
  const southRegion = ee.Geometry.Point([-19.62, 63.13]).buffer(50000); // ~50km south

  const startDate = '2010-05-10';
  const endDate = '2010-05-11';

  // 2. Data Acquisition - MODIS Aerosol for volcanic plume detection
  let aerosolCol = ee.ImageCollection('MODIS/006/MCD19A2_GRANULES')
    .filterDate(startDate, endDate)
    .filterBounds(volcanoPoint);

  console.log('MCD19A2 Images:', aerosolCol.size().getInfo());

  // Fallback to older MODIS aerosol product
  if (aerosolCol.size().getInfo() === 0) {
    aerosolCol = ee.ImageCollection('MODIS/006/MOD08_D3')
      .filterDate(startDate, endDate);
    console.log('MOD08_D3 Images:', aerosolCol.size().getInfo());
  }

  // Another fallback to Terra/Aqua combined
  if (aerosolCol.size().getInfo() === 0) {
    aerosolCol = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
      .filterDate(startDate, endDate)
      .filterBounds(volcanoPoint);
    console.log('MCD19A2_061 Images:', aerosolCol.size().getInfo());
  }

  if (aerosolCol.size().getInfo() === 0) {
    console.log('No data available for May 10, 2010.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - get aerosol optical depth
  const aerosolImage = aerosolCol.median();
  const aodBand = aerosolImage.select(['Optical_Depth_055']).multiply(0.001); // Scale factor

  // Check for valid pixels in both regions
  const northCount = aodBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_055');

  const southCount = aodBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_055');

  const northCountVal = await northCount.getInfo();
  const southCountVal = await southCount.getInfo();

  console.log('North pixels:', northCountVal, 'South pixels:', southCountVal);

  if (!northCountVal || !southCountVal || northCountVal === 0 || southCountVal === 0) {
    console.log('No valid pixels in one or both regions.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - mean AOD in each region
  const northMean = aodBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_055');

  const southMean = aodBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('Optical_Depth_055');

  const northVal = await northMean.getInfo();
  const southVal = await southMean.getInfo();

  console.log('North AOD:', northVal);
  console.log('South AOD:', southVal);

  // 5. Validation & Final Answer
  if (northVal === null || southVal === null || isNaN(northVal) || isNaN(southVal)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log('North/South ratio:', (northVal / southVal).toFixed(2));

  // If northern AOD is greater, plume went north
  if (northVal > southVal) {
    console.log('Primary plume direction: NORTH');
    console.log('<answer>A</answer>');
  } else {
    console.log('Primary plume direction: SOUTH');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
